//! The component registry (generated by `scripts/gen-cli-registry.sh` from the gallery).

use serde_json::Value;

static REGISTRY: &str = include_str!("../registry.json");

#[derive(Clone, Debug)]
pub struct Component {
    pub id: String,
    pub name: String,
    pub category: String,
    pub krate: String,
    pub description: String,
    pub code: String,
}

pub fn load() -> Vec<Component> {
    let v: Value = serde_json::from_str(REGISTRY).expect("embedded registry.json is valid");
    let s = |x: &Value, k: &str| x.get(k).and_then(Value::as_str).unwrap_or_default().to_string();
    v.as_array()
        .map(|a| {
            a.iter()
                .map(|x| Component {
                    id: s(x, "id"),
                    name: s(x, "name"),
                    category: s(x, "category"),
                    krate: s(x, "crate"),
                    description: s(x, "description"),
                    code: s(x, "code"),
                })
                .collect()
        })
        .unwrap_or_default()
}

/// Case-insensitive search over id, name, category and description. Every word must match.
pub fn search<'a>(all: &'a [Component], query: &str) -> Vec<&'a Component> {
    let words: Vec<String> = query.split_whitespace().map(str::to_lowercase).collect();
    all.iter()
        .filter(|c| {
            let hay = format!("{} {} {} {} {}", c.id, c.name, c.category, c.krate, c.description).to_lowercase();
            words.iter().all(|w| hay.contains(w))
        })
        .collect()
}

/// Closest ids to a misspelled one.
pub fn suggest<'a>(all: &'a [Component], id: &str) -> Vec<&'a str> {
    let mut scored: Vec<(usize, &str)> = all.iter().map(|c| (distance(&c.id, id), c.id.as_str())).collect();
    scored.sort();
    scored.into_iter().take(3).filter(|(d, _)| *d <= id.len().max(4) / 2 + 2).map(|(_, s)| s).collect()
}

fn distance(a: &str, b: &str) -> usize {
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for (i, ca) in a.chars().enumerate() {
        let mut cur = vec![i + 1; b.len() + 1];
        for (j, cb) in b.iter().enumerate() {
            cur[j + 1] = (prev[j] + usize::from(ca != *cb)).min(prev[j + 1] + 1).min(cur[j] + 1);
        }
        prev = cur;
    }
    prev[b.len()]
}
